import {I18N} from '@gravity-ui/i18n';
import en from './keysets/en.json';
import ru from './keysets/ru.json';

export type AppLang = 'en' | 'ru';

export const i18nInstance = new I18N();
i18nInstance.registerKeysets('en', en);
i18nInstance.registerKeysets('ru', ru);
i18nInstance.setLang('en');

export const i18n = i18nInstance.keyset('app');
```
Wait — keyset is typed loosely? I18N class methods accept keyset name string and key string, returns string. Fine untyped.

Also a subscription mechanism: I18N doesn't have subscribe. I'll make a tiny lang store:
```ts
type Listener = () => void;
let lang: AppLang = 'en';
const listeners = new Set<Listener>();
export function getLang() { return lang; }
export function setLang(next: AppLang) {
  lang = next;
  i18nInstance.setLang(next);
  configure({lang: next}); // uikit
  listeners.forEach(l => l());
}
export function subscribeLang(l: Listener) { listeners.add(l); return () => listeners.delete(l); }
```
And `useLang` hook via `useSyncExternalStore`.

